   * behind this page.
   */
  const [initial] = useState(() => ({
    kind: (definition ? definition.type : startAs) as TaskKind,
    id: definition?.id,
    name: definition?.name ?? '',
    presetId: definition?.presetId ?? presets[0]?.id ?? '',
    trialCount: definition?.trialCount ?? 10,
    rows: !definition
      ? []
      : isReversalDefinition(definition)
        ? definition.reversals.map(
            (entry): DraftRow => ({
              key: mintKey(),
              label: entry.label,
              // Filler was stored with none; give it the starting set so the
              // row is editable the moment it is switched back to scored.
              rules: toDraftRules(
                entry.rules.length > 0 ? toPlain(entry.rules) : STARTING_REVERSAL_RULES
              ),
              ignore: entry.ignore === true,
              settings: toPlain(entry.settings)
            })
          )
        : definition.entries.map(
            (entry): DraftRow => ({
              key: mintKey(),
              label: entry.label,
              rules: toDraftRules(entry.rules.length > 0 ? toPlain(entry.rules) : STARTING_RULES),
              ignore: entry.ignore === true,
              recordingId: entry.recordingId
            })
          )
  }))

  const kind = initial.kind
  const editingId = initial.id

  const [name, setName] = useState(initial.name)
  const [presetId, setPresetId] = useState(initial.presetId)
  const [trialCount, setTrialCount] = useState(initial.trialCount)
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [entries, setEntries] = useState<DraftRow[]>(initial.rows)
  /**
   * The action rule the move picker is filling, or null when it is closed.
   * Addressed by stable keys, not indices — the same reason DraftRule carries
   * one: an index captured when the dialog opened would dangle after a
   * reorder or removal happening... it cannot mid-dialog today, but keys make
   * that unrepresentable rather than merely unlikely.
   */
  const [pickingFor, setPickingFor] = useState<{ entryKey: string; ruleKey: string } | null>(null)

  const used = new Set(entries.map((entry) => entry.recordingId))
  const available = records.filter((record) => !used.has(record.id))

  /*
   * Every configured reversal the dummy holds, flattened with its place.
   *
   * Unset rows are dropped — an entry nobody has filled in names no move, so
   * there is nothing to practise and nothing to say about it — but INACTIVE ones
   * are kept and marked. A drill declares which reversals it wants active, so
   * authoring one against a reversal that happens to be switched off right now
   * is legitimate; refusing it here would force a trip to the pause menu just to
   * write the drill down.
   */
  const configured: { place: ReversalPlace; entry: LiveReversalEntry }[] = []
  if (reversals) {
    for (const group of TASK_REVERSAL_GROUPS) {
      for (const entry of reversals[group] ?? []) {
        if (isUnsetEntry(entry)) continue
        if (buildReversalWitness(entry)) configured.push({ place: { group, slot: entry.slot }, entry })
      }
    }
  }

  /** Already in this drill — matched on settings, as everywhere. */
  function isTakenEntry(candidate: LiveReversalEntry): boolean {
    const witness = buildReversalWitness(candidate)
    return (
      witness !== null &&
      entries.some((entry) => entry.settings && witnessEquals(entry.settings, witness))
    )
  }

  /** What the board still offers. The board recomputes this through `isTaken`;
   * this copy exists for the add-all button, which needs the places. */
  const availableReversals = configured.filter((candidate) => !isTakenEntry(candidate.entry))

  // ── Immutable draft updates ─────────────────────────────────────────
  //
  // The Svelte version mutated in place and reassigned (`rules.splice(...);
  // entries = entries`), which its deep proxies turned into updates. React sees
  // none of that — a mutated array is the same reference, so nothing re-renders
  // and nothing saves. Every change below builds new rows.

  function patchEntry(index: number, patch: Partial<DraftRow>): void {
    setEntries((held) => held.map((entry, i) => (i === index ? { ...entry, ...patch } : entry)))
  }

  function patchRule(entryIndex: number, ruleIndex: number, patch: Partial<DraftRule>): void {
    setEntries((held) =>
      held.map((entry, i) =>
        i === entryIndex
          ? {
              ...entry,
              rules: entry.rules.map((rule, j) => (j === ruleIndex ? { ...rule, ...patch } : rule))
            }
          : entry
      )
    )
  }

  function addRecording(recordId: string): void {
    const record = records.find((candidate) => candidate.id === recordId)
    if (!record) return
    setEntries((held) => [
      ...held,
      {
        key: mintKey(),
        recordingId: record.id,
        label: record.title,
        ignore: false,
        rules: toDraftRules(STARTING_RULES)
      }
    ])
  }

  /**
   * Copies a live reversal's settings into the drill.
   *
   * Snapshotted, not referenced — that copy IS the drill's durable identity from
   * here on, and the row it was taken from can be re-pointed at another move
   * tomorrow without touching what this drill means.
   */
  function addReversal(place: ReversalPlace): void {
    const found = configured.find(
      (candidate) => candidate.place.group === place.group && candidate.place.slot === place.slot
    )
    if (!found) return

    const settings = buildReversalWitness(found.entry)
    if (!settings) return

    const named = moveNameFor(catalogue, reversalsFor, settings, catalogueLanguage)
    setEntries((held) => [
      ...held,
      {
        key: mintKey(),
        settings,
        label: [named, tuningOf(found.entry)].filter(Boolean).join(' · ').slice(0, 80),
        ignore: false,
        rules: toDraftRules(STARTING_REVERSAL_RULES)
      }
    ])
  }

  /**
   * Every switched-on reversal the board still offers, in one press — the whole
   * roster of what the dummy would actually do, which is the commonest drill.
   * Off ones are left out on purpose: they were switched off in the game, and
   * bulk-adding them would bake a decision the author made the other way.
   */
  const activeAvailable = availableReversals.filter((candidate) =>
    isReversalActive(candidate.entry)
  )
  function addAllActive(): void {
    for (const candidate of activeAvailable) addReversal(candidate.place)
  }

  /**
   * Where this drill's reversal currently sits, or null if nowhere.
   *
   * Display only — the row is identified by its settings, and this is the same
   * lookup materialization does, shown so the author can see which pause-menu
   * row they are talking about right now.
   */
  function placeOf(entry: DraftRow): { place: ReversalPlace; active: boolean } | null {
    if (!entry.settings) return null
    for (const candidate of configured) {
      const witness = buildReversalWitness(candidate.entry)
      if (witness && witnessEquals(witness, entry.settings)) {
        return { place: candidate.place, active: isReversalActive(candidate.entry) }
      }
    }
    return null
  }

  function removeEntry(index: number): void {
    setEntries((held) => held.filter((_, i) => i !== index))
  }

  function addRule(entryIndex: number): void {
    setEntries((held) =>
      held.map((entry, i) => {
        if (i !== entryIndex) return entry
        // Before any trailing catch-all, since a rule after it can never match.
        const elseAt = entry.rules.findIndex((rule) => rule.when === 'else')
        const at = elseAt === -1 ? entry.rules.length : elseAt
        return {
          ...entry,
          rules: entry.rules.toSpliced(at, 0, {
            key: mintKey(),
            when: 'damage',
            points: 1,
            actionText: ''
          })
        }
      })
    )
  }

  function removeRule(entryIndex: number, ruleIndex: number): void {
    setEntries((held) =>
      held.map((entry, i) =>
        i === entryIndex ? { ...entry, rules: entry.rules.toSpliced(ruleIndex, 1) } : entry
      )
    )
  }

  function moveRule(entryIndex: number, ruleIndex: number, by: number): void {
    setEntries((held) =>
      held.map((entry, i) => {
        if (i !== entryIndex) return entry
        const to = ruleIndex + by
        if (to < 0 || to >= entry.rules.length) return entry
        const rules = entry.rules.toSpliced(ruleIndex, 1)
        return { ...entry, rules: rules.toSpliced(to, 0, entry.rules[ruleIndex]) }
      })
    )
  }

  /**
   * Folds a pick's ActionIDs into the rule the picker was opened for.
   *
   * Appended to the free text rather than replacing it — the text stays the
   * source of truth and stays hand-editable, so the picker is an input aid and
   * not a second storage format. Ids the text already carries are not repeated,
   * which is what lets "pick another strength of the same move" accumulate.
   */
  function insertActionIds(ids: number[]): void {
    const target = pickingFor
    setPickingFor(null)
    if (!target) return
    setEntries((held) =>
      held.map((entry) =>
        entry.key !== target.entryKey
          ? entry
          : {
              ...entry,
              rules: entry.rules.map((rule) => {
                if (rule.key !== target.ruleKey) return rule
                const present = new Set(
                  rule.actionText
                    .split(/[,\s]+/)
                    .filter((part) => /^\d+$/.test(part))
                    .map(Number)
                )
                // `present` grows as it goes, so a duplicate INSIDE `ids` is
                // dropped too, not only ids the text already had.
                const fresh: number[] = []
                for (const id of ids) {
                  if (present.has(id)) continue
                  present.add(id)
                  fresh.push(id)
                }
                if (fresh.length === 0) return rule
                const text = rule.actionText.trim()
                return {
                  ...rule,
                  actionText: text ? `${text}, ${fresh.join(', ')}` : fresh.join(', ')
                }
              })
            }
      )
    )
  }

  /** True when a trial matching none of the rules would simply score nothing. */
  function lacksElse(entry: DraftRow): boolean {
    return !entry.rules.some((rule) => rule.when === 'else')
  }

  function titleOf(recordingId: string): string | null {
    return records.find((record) => record.id === recordingId)?.title ?? null
  }

  async function save(): Promise<void> {
    setError(null)

    if (!presetId) {
      setError('Choose a Training Preset for this drill.')
      return
    }

    if (entries.length === 0) {
      setError(
        kind === 'reversalResponse' ? m.editor.needOneReversal() : m.editor.needOneRecording()
      )
      return
    }

    // A drill of nothing but filler would arm a session whose trial counter can
    // never move. The mod refuses that spec; refusing it here saves a round trip
    // and says it in the author's own terms.
    if (entries.every((entry) => entry.ignore)) {
      setError(m.editor.needOneGraded())
      return
    }

    // Fold the free-text action ids back into the rules, refusing anything that
    // is not a number rather than dropping it — a typo'd id is a rule that would
    // silently never match, which is the failure the mod refuses a spec over.
    //
    // Filler contributes an empty set and skips the check: its rules exist only
    // in the draft, and validating ids nobody will ever evaluate would block a
    // save over a row the drill does not score.
    const ruleSets: TaskRule[][] = []
    for (const entry of entries) {
      if (entry.ignore) {
        ruleSets.push([])
        continue
      }

      const rules: TaskRule[] = []
      for (const [ruleIndex, rule] of entry.rules.entries()) {
        if (rule.when !== 'action') {
          rules.push({ when: rule.when, points: rule.points })
          continue
        }

        const parts = rule.actionText
          .split(/[,\s]+/)
          .map((part) => part.trim())
          .filter((part) => part.length > 0)

        if (parts.some((part) => !/^\d+$/.test(part))) {
          setError(m.editor.idsMustBeNumbers(entry.label, ruleIndex + 1))
          return
        }
        if (parts.length === 0) {
          setError(m.editor.idsRequired(entry.label, ruleIndex + 1))
          return
        }

        rules.push({ when: 'action', points: rule.points, actionIds: parts.map(Number) })
      }
      ruleSets.push(rules)
    }

    // The one place the two kinds diverge. A row whose per-kind field is missing
    // cannot be built, and that is a bug rather than user input — so it refuses
    // loudly here instead of being dropped into a drill that then practises less
    // than it says it does.
    const now = new Date().toISOString()
    const common = {
      schema: 2 as const,
      id: editingId ?? crypto.randomUUID(),
      name: name.trim(),
      presetId,
      characterName,
      trialCount,
      createdAt: definition?.createdAt ?? now,
      updatedAt: now
    }
    let draft: TaskDefinition

    if (kind === 'reversalResponse') {
      const rows = entries.map((entry, index) => ({
        settings: entry.settings,
        label: entry.label,
        ...(entry.ignore && { ignore: true as const }),
        rules: ruleSets[index]
      }))
      const broken = rows.find((row) => !row.settings)
      if (broken) {
        setError(m.editor.lostSettings(broken.label))
        return
      }
      draft = TaskDefinitionSchema.parse({
        ...common,
        type: 'reversalResponse',
        reversals: rows as {
          settings: TaskReversalWitness
          label: string
          ignore?: true
          rules: TaskRule[]
        }[]
      })
    } else {
      const rows = entries.map((entry, index) => ({
        recordingId: entry.recordingId,
        label: entry.label,
        ...(entry.ignore && { ignore: true as const }),
        rules: ruleSets[index]
      }))
      const broken = rows.find((row) => !row.recordingId)
      if (broken) {
        setError(m.editor.lostRecording(broken.label))
        return
      }
      draft = TaskDefinitionSchema.parse({
        ...common,
        type: 'slotResponse',
        entries: rows as {
          recordingId: string
          label: string
          ignore?: true
          rules: TaskRule[]
        }[]
      })
    }

    setBusy(true)
    try {
      await onSave(draft)
      onClose()
    } catch (failure) {
      // Without this the page just sat there: the rejection went nowhere, so a
      // save that never reached main looked exactly like an unwired button.
      setError(`${String(failure)}`)
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <header className="flex items-center gap-3">
        <button onClick={onClose}>← {m.editor.back()}</button>
        <div className="flex items-baseline gap-2">
          <h2 className="text-xl font-semibold">
            {editingId ? m.editor.editTitle() : m.editor.newTitle()}
          </h2>
          <span className="rounded-full border border-border px-2 py-[0.05rem] text-xs text-muted-foreground">
            {characterName}
          </span>
          {/* Fixed once the drill exists: the two kinds address completely
              different stimuli, so switching would throw away every row rather
              than convert it, and there is nothing to gain over creating a
              second drill. */}
          <span className="rounded-full border border-border px-2 py-[0.05rem] text-xs text-muted-foreground">
            {kind === 'reversalResponse' ? m.editor.kindReversal() : m.editor.kindSlot()}
          </span>
        </div>
        <button className="primary ml-auto px-6 py-2 text-sm" onClick={() => void save()} disabled={busy}>
          {busy ? m.editor.saving() : m.editor.save()}
        </button>
      </header>


[330 more lines in file. Use offset=670 to continue.]

      {error ? <Notice tone="bad">{error}</Notice> : null}

      <section className="flex gap-4">
        <label className={cn(FIELD, 'flex-1')}>
          <span>{m.editor.name()}</span>
          <input
            type="text"
            value={name}
            onChange={(event) => setName(event.currentTarget.value)}
            placeholder={m.editor.namePlaceholder()}
            maxLength={80}
            className={INPUT}
          />
        </label>
        <label className={cn(FIELD, 'min-w-64')}>
          <span>Training Preset</span>
          <select
            value={presetId}
            onChange={(event) => setPresetId(event.currentTarget.value)}
            className={INPUT}
          >
            {presetId && !presets.some((preset) => preset.id === presetId) ? (
              <option value={presetId}>Missing preset ({presetId})</option>
            ) : null}
            {presets.length === 0 && !presetId ? <option value="">No presets available</option> : null}
            {presets.map((preset) => (
              <option key={preset.id} value={preset.id}>
                {preset.name}
              </option>
            ))}
          </select>
        </label>
        <label className={FIELD}>
          <span>{m.editor.trials()}</span>
          <input
            type="number"
            min={TASK_MIN_TRIALS}
            max={TASK_MAX_TRIALS}
            value={trialCount}
            onChange={(event) => {
              // A half-typed field parses to NaN; ignoring it leaves the last
              // good value rather than snapping to something invented.
              const next = event.currentTarget.valueAsNumber
              if (Number.isFinite(next)) setTrialCount(next)
            }}
            className={cn(INPUT, 'w-24')}
          />
        </label>
      </section>

      <section className="flex flex-col gap-2">
        <div className="flex flex-wrap items-baseline gap-3">
          <h3 className="text-base font-semibold">{m.editor.behaviours()}</h3>
          <span className={DIM}>{entries.length}</span>

          {kind === 'reversalResponse' && configured.length === 0 ? (
            <span className={DIM}>{m.editor.noneConfigured()}</span>
          ) : null}

          {/* Page-level, not a board affordance: it acts on the same candidates
              the board shows, but what "add" means belongs to this page. Hidden
              with one candidate left — the button would just restate the row. */}
          {kind === 'reversalResponse' && activeAvailable.length > 1 ? (
            <button className={cn(CANDIDATE, 'text-xs')} onClick={addAllActive}>
              {m.editor.addAllActive()}
            </button>
          ) : null}
        </div>

        {kind === 'reversalResponse' ? (
          /* The same board the Dummy view shows — the dummy's three reversal lists,
             all at once. Here it is a picker: pressing an entry copies its
             settings into the drill, and entries already in the drill drop out
             of the board. */
          <ReversalBoard
            reversals={reversals}
            reversalsFor={reversalsFor}
            catalogue={catalogue}
            onPick={addReversal}
            isTaken={isTakenEntry}
          />
        ) : available.length > 0 ? (
          <div className="flex flex-wrap gap-2">
            {available.map((record) => (
              <button key={record.id} onClick={() => addRecording(record.id)} className={CANDIDATE}>
                {record.title}
              </button>
            ))}
          </div>
        ) : records.length === 0 ? (
          <span className={DIM}>{m.editor.noRecordings(characterName)}</span>
        ) : (
          <span className={DIM}>{m.editor.allRecordingsAdded(characterName)}</span>
        )}
      </section>

      {entries.length === 0 ? (
        <p className="m-0 max-w-[70ch] rounded-md border border-dashed border-border px-4 py-6 text-sm leading-[1.6] text-dim">
          {kind === 'reversalResponse' ? m.editor.emptyReversal() : m.editor.emptySlot()}
        </p>
      ) : null}

      <div className="flex flex-col gap-4">
        {entries.map((entry, entryIndex) => {
          const sits = kind === 'reversalResponse' ? placeOf(entry) : null
          const liveTitle =
            kind !== 'reversalResponse' && entry.recordingId ? titleOf(entry.recordingId) : null

          return (
            <section
              key={entry.key}
              className="flex flex-col gap-3 rounded-md border border-border bg-card p-4"
            >
              <header className="flex items-center gap-3">
                <input
                  type="text"
                  value={entry.label}
                  onChange={(event) => patchEntry(entryIndex, { label: event.currentTarget.value })}
                  maxLength={80}
                  className={cn(INPUT, 'flex-1 text-base font-semibold')}
                />

                {kind === 'reversalResponse' ? (
                  sits === null ? (
                    /* Nothing on the dummy holds these settings right now. The
                       drill is still valid — it describes a behaviour, not a
                       row — but it cannot run until the setting exists again, so
                       say so here rather than at the moment somebody presses
                       Run. */
                    <span className={WARN} title={JSON.stringify(entry.settings, null, 1)}>
                      {m.editor.notConfigured()}
                    </span>
                  ) : (
                    /* Dim on purpose: where the reversal currently sits is the
                       one thing on the row that is NOT part of the drill, and
                       reading it as the identity is exactly the mistake this
                       whole layer exists to prevent. The list it sits in is the
                       exception — that one IS what the drill practises, so it
                       is named rather than left as the raw group key. */
                    <span
                      className={cn(
                        'inline-flex items-center gap-[0.4rem] rounded-full border px-[0.45rem] py-[0.05rem] text-xs tabular-nums text-muted-foreground',
                        sits.active ? 'border-border' : 'border-danger-edge'
                      )}
                      title={
                        (sits.active ? '' : `${m.reversalBoard.switchedOff()}\n\n`) +
                        JSON.stringify(entry.settings, null, 1)
                      }
                    >
                      {/* The same mark as the picker's, so "off" looks like one
                          thing across the page rather than two. */}
                      {!sits.active ? <OffMark /> : null}
                      {m.reversalGroup[sits.place.group].title()} {sits.place.slot}
                    </span>
                  )
                ) : liveTitle === null ? (
                  <span className={WARN} title={entry.recordingId}>
                    {m.editor.deleted()}
                  </span>
                ) : liveTitle !== entry.label ? (
                  <span className={WARN}>{m.editor.renamedTo(liveTitle)}</span>
                ) : null}

                {/* In the rotation, out of the scoring. A row rather than a
                    separate list because it is the same behaviour with one thing
                    turned off, and splitting the two would mean picking the
                    recording twice. Pushed to the right edge beside Remove: it is
                    a property of the whole row, not one more field in the middle
                    of the identity. */}
                <label className="ml-auto inline-flex items-center gap-2 text-xs whitespace-nowrap text-muted-foreground">
                  <input
                    type="checkbox"
                    checked={entry.ignore}
                    onChange={(event) =>
                      patchEntry(entryIndex, { ignore: event.currentTarget.checked })
                    }
                    className="p-0"
                  />
                  <span>{m.editor.filler()}</span>
                </label>

                <button className={GHOST} onClick={() => removeEntry(entryIndex)}>
                  {m.editor.remove()}
                </button>
              </header>

              {entry.ignore ? (
                <p className={DIM}>{m.editor.fillerNote()}</p>
              ) : (
                <>
                  <div className="flex items-baseline gap-3">
                    <h4 className="text-sm font-semibold">{m.editor.rules()}</h4>
                    <p className={DIM}>{m.editor.rulesNote()}</p>
                  </div>

                  {/* The rail is the ordering, drawn: a line down the left of the
                      list, so "these are evaluated in this order, top down" is a
                      thing you see rather than a thing you read. */}
                  <ol className="m-0 flex list-none flex-col gap-1 border-l-2 border-surface-2 py-0 pr-0 pl-4">
                    {entry.rules.map((rule, ruleIndex) => (
                      <li key={rule.key} className="flex items-center gap-2">
                        <span className="w-[1.4rem] text-xs tabular-nums text-muted-foreground">
                          {ruleIndex + 1}
                        </span>

                        <select
                          value={rule.when}
                          onChange={(event) =>
                            patchRule(entryIndex, ruleIndex, {
                              when: event.currentTarget.value as TaskRuleWhen
                            })
                          }
                          className={cn(INPUT, 'w-36')}
                        >
                          {TASK_RULE_WHENS.map((when) => (
                            <option key={when} value={when}>
                              {m.editor.when[when]()}
                            </option>
                          ))}
                        </select>

                        <span className="flex-1 text-xs text-dim">
                          {m.editor.whenHelp[rule.when]()}
                        </span>

                        {rule.when === 'action' ? (
                          <>
                            <input
                              type="text"
                              placeholder="700, 810"
                              value={rule.actionText}
                              onChange={(event) =>
                                patchRule(entryIndex, ruleIndex, {
                                  actionText: event.currentTarget.value
                                })
                              }
                              title={m.editor.actionIdsHint()}
                              className={cn(INPUT, 'w-40')}
                            />
                            {/* Only with a catalogue to draw from: without one
                                the button could open nothing but an empty
                                dialog, and the free text still works. */}
                            {catalogue ? (
                              <button
                                data-ui="pick-move"
                                data-key={`${entryIndex}-${ruleIndex}`}
                                className={GHOST}
                                onClick={() =>
                                  setPickingFor({ entryKey: entry.key, ruleKey: rule.key })
                                }
                              >
                                {m.editor.pickMove()}
                              </button>
                            ) : null}
                          </>
                        ) : null}

                        <input
                          type="number"
                          value={rule.points}
                          onChange={(event) => {
                            const next = event.currentTarget.valueAsNumber
                            if (Number.isFinite(next)) patchRule(entryIndex, ruleIndex, { points: next })
                          }}
                          className={cn(INPUT, 'w-20 text-right tabular-nums')}
                        />

                        <div className="flex gap-1">
                          <button
                            className={GHOST}
                            disabled={ruleIndex === 0}
                            onClick={() => moveRule(entryIndex, ruleIndex, -1)}
                            title={m.editor.earlier()}
                          >
                            ↑
                          </button>
                          <button
                            className={GHOST}
                            disabled={ruleIndex === entry.rules.length - 1}
                            onClick={() => moveRule(entryIndex, ruleIndex, 1)}
                            title={m.editor.later()}
                          >
                            ↓
                          </button>
                          <button
                            className={GHOST}
                            disabled={entry.rules.length === 1}
                            onClick={() => removeRule(entryIndex, ruleIndex)}
                            title={m.editor.remove()}
                          >
                            ✕
                          </button>
                        </div>
                      </li>
                    ))}
                  </ol>

                  <footer className="flex items-center gap-3">
                    <button className={GHOST} onClick={() => addRule(entryIndex)}>
                      {m.editor.addRule()}
                    </button>
                    {lacksElse(entry) ? <span className={WARN}>{m.editor.lacksElse()}</span> : null}
                  </footer>
                </>
              )}
            </section>
          )
        })}
      </div>

      {kind === 'reversalResponse' && entries.length > 0 ? (
        /* The set is the difficulty. Saying so where the drill is written is the
           cheapest place to make it land, because the number this drill produces
           is only comparable to its other runs if the dummy offers the same
           options. */
        <Notice tone="caution">{m.editor.rosterNote(entries.length)}</Notice>
      ) : null}

      {pickingFor !== null && catalogue ? (
        <MovePickerDialog
          catalogue={catalogue}
          defaultCharacter={characterName}
          onPick={insertActionIds}
          onClose={() => setPickingFor(null)}
        />
      ) : null}
    </>
  )
}

