export function isBlocked(contact: ContactLike): boolean {
	return (
		(contact.guardSt & TASK_GUARDING) !== 0 ||
		(contact.attr & (TASK_ATTR.grd | TASK_ATTR.dGrd | TASK_ATTR_BLOCKING)) !== 0
