/** The derived booleans a trial supports. `Predicate.summarize`'s shape. */
export interface TrialSummary {
	/** A player attack landed on the dummy as a hit. */
	damage: boolean;
	/** A contact on the dummy carried the counter flag. */
	counter: boolean;
	/** A contact on the dummy carried the punish-counter flag. */
	punish: boolean;
	/** The player blocked something. */
	block: boolean;
	/** The player was hit. */
	got_hit: boolean;
	/**
