	thrown: boolean;
}

export function summarizeTrial(trial: TaskTrial): TrialSummary {
	const dummy = trial.dummyReceived;
	const player = trial.playerReceived;

	return {
		damage: dummy.some((contact) => (contact.attr & TASK_ATTR.hit) !== 0),
		counter: dummy.some((contact) => contact.counter),
		punish: dummy.some((contact) => contact.punish),
		block: player.some(isBlocked),
		got_hit: player.some((contact) => (contact.attr & TASK_ATTR.hit) !== 0),
		thrown: trial.dummyCaught
	};
}

export interface Grade {
	/** 1-based, matching the mod's `matchedRule`. */
	matchedRule: number;
	points: number;
	when: TaskRuleWhen;
