 * Null when nothing matched — a rule list that wants a guaranteed answer ends
 * with `else`. A trial carrying a diagnostic is not scored at all
 * (TASK_PROTOCOL.md §4); that is the caller's check, not this one's, because
 * "what would this have scored" is a question worth being able to ask about an
 * unscored trial.
 */
export function evaluateTrial(trial: TaskTrial, rules: readonly TaskRule[]): Grade | null {
	const summary = summarizeTrial(trial);

	for (let index = 0; index < rules.length; index += 1) {
		const rule = rules[index];

		const matched =
			rule.when === 'else'
				? true
				: rule.when === 'action'
					? (rule.actionIds ?? []).some((id) => trial.playerActionIds.includes(id))
					: summary[rule.when];

		if (matched) return { matchedRule: index + 1, points: rule.points, when: rule.when };
	}

	return null;
}

