 * flags, have moved since — which is either a rule the user edited, or a bug one
 * of the two implementations has just stopped having.
 */
export interface Regrade {
	trial: TaskTrial;
	grade: Grade | null;
	/** What the mod stored at the time. Null for an unscored (diagnostic) trial. */
	recordedPoints: number | null;
	changed: boolean;
}

