	trials: readonly TaskTrial[],
	rulesFor: (trial: TaskTrial) => readonly TaskRule[] | undefined
): Regrade[] {
	return trials.map((trial) => {
		const rules = trial.diagnostic === null ? rulesFor(trial) : undefined;
		const grade = rules ? evaluateTrial(trial, rules) : null;

		return {
			trial,
			grade,
			recordedPoints: trial.points,
			changed: (grade?.points ?? null) !== trial.points
