export interface ActionSemantic {
	semanticId: string;
	name: string;
	variant: string | null;
	notationClassic: string;
	notationModern: string;
	actionIds: number[];
}

export interface ActionSemanticCatalogue {
	sf6BuildId: string | null;
	characterId: number | null;
	characterName: string;
	byActionId: ReadonlyMap<number, readonly ActionSemantic[]>;
}

function semanticFor(
	key: CatalogueKey | typeof SYSTEM_KEY,
	row: CatalogueRow,
	slot: number | null,
	name: string,
	variant: string | null,
	notationClassic: string,
	notationModern: string,
	actionIds: number[]
): ActionSemantic {
	return {
		semanticId: `${key}:${row.index}${slot === null ? '' : `:${slot}`}`,
		name,
		variant,
		notationClassic,
		notationModern,
		actionIds: [...new Set(actionIds)]
	};
}

/** Builds the ActionID resolver from the existing shipped reversal/system catalogue. */
export function buildActionSemanticCatalogue(
	catalogue: ReversalCatalogue,
	characterName: string,
	language?: CatalogueLanguage
): ActionSemanticCatalogue | null {
	const character = catalogue.characters[characterName];
	if (!character) return null;
	const byActionId = new Map<number, ActionSemantic[]>();

	function add(semantic: ActionSemantic): void {
		for (const actionId of semantic.actionIds) {
			const entries = byActionId.get(actionId) ?? [];
			if (!entries.some((entry) => entry.semanticId === semantic.semanticId)) {
				entries.push(semantic);
				byActionId.set(actionId, entries);
			}
		}
	}

	for (const key of [...CATALOGUE_KEYS, SYSTEM_KEY] as const) {
		for (const row of character[key] ?? []) {
			if (!row.name || !row.actions || row.actions.length === 0) continue;
			// SYSTEM ids are hand-maintained rather than joined from the stamped
			// ActionMap. They need their own exact-build measurement and must not be
			// promoted from inferred/MMDK rows or legacy "current build" prose.
			if (
				key === SYSTEM_KEY &&
				(row.confidence !== 'confirmed' ||
					row.unverified === true ||
					!catalogue.sf6BuildId ||
					row.sf6BuildId !== catalogue.sf6BuildId)
			) {
				continue;
			}
			const perVariant = row.strengths !== null && row.strengths.length === row.actions.length;
			const displayName = localisedName(row.names, language) ?? row.name;
			if (perVariant) {
				row.actions.forEach((action, slot) => {
					const strength = row.strengths?.[slot] ?? null;
					const command = row.commandsByLevel?.[slot];
					add(
						semanticFor(
							key,
							row,
							slot,
							displayName as string,
							strength === null ? null : strengthLabel(catalogue, strength, language),
							row.semanticNotation ?? command?.classic ?? row.commandClassic,
							row.semanticNotation ?? command?.modern ?? row.commandModern,
							[action.actionId, ...action.continuations]
						)
					);
				});
			} else {
				add(
					semanticFor(
						key,
						row,
						null,
						displayName,
						null,
						row.semanticNotation ?? row.commandClassic,
						row.semanticNotation ?? row.commandModern,
						row.actions.flatMap((action) => [action.actionId, ...action.continuations])
					)
				);
			}
		}
	}

	return {
		sf6BuildId: catalogue.sf6BuildId ?? null,
		characterId: character.characterId ?? null,
		characterName,
		byActionId
	};
}

