/**
 * Reads the training-task session stream.
 *
 * `fgcnote/task/session.json` is the whole session in one file, rewritten
 * atomically by the mod on start, on every resolved trial, and on end
 * (TASK_PROTOCOL.md §3). There is no event log to tail — the file *is* the log,
 * and reading it means reading all of it.
 *
 * ## Why this is not part of state.ts
 *
 * state.ts answers "what does the game look like, and is the mod alive". This
 * answers "what has the player scored so far", from a different folder, on a
 * different cadence, with a different failure meaning: a missing session.json is
 * the ordinary state of an install that has never run a session, whereas a
 * missing recording_slots.json is a problem. Folding the two together would mean one
 * poll's failure mode standing in for the other's.
 *
 * ## Why it polls, and what keeps it cheap
 *
 * Same reasoning state.ts gives for not using fs.watch: it is unsupported on
 * some filesystems and reports that by doing nothing, which is indistinguishable
 * from a quiet session.
 *
 * Like every bridge file, the cheap gate is the file's own
 * mtime and size. A session that is not moving costs one stat per poll; the
 * document is only parsed when the bytes change. That matters because a 500-trial
 * session is a large document and the poll runs several times a second — the
 * rate has to be fast enough that a resolved trial appears while the player is
 * still thinking about it.
 */

import { readFile, stat } from 'node:fs/promises'
import { join } from 'node:path'
import { parseTaskSession } from '@fgcnote/shared/recording/training-task-bridge'
import type { TaskSessionView } from '../shared/types'

const SESSION_FILE = 'session.json'

/**
 * How often the file is checked.
 *
 * A trial resolves the moment a playback ends and the next one starts
 * immediately, so this is the delay between the player finishing an answer and
 * seeing it graded. Deliberately faster than the 1s recording poll, and
 * affordable because an unchanged file costs a stat.
 */
const POLL_MS = 400

/** Pause before a second attempt at a file that was missing or unparseable. */
const RETRY_DELAY_MS = 120

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

type RawRead =
  | { ok: true; value: unknown }
  | { ok: false; code: 'missing' | 'torn'; detail: string }

async function readJsonOnce(file: string): Promise<RawRead> {
  let text: string
  try {
    text = await readFile(file, 'utf-8')
  } catch (error) {
    const errno = (error as NodeJS.ErrnoException).code
    return { ok: false, code: errno === 'ENOENT' ? 'missing' : 'torn', detail: String(error) }
  }

  try {
    return { ok: true, value: JSON.parse(text) as unknown }
  } catch (error) {
    return { ok: false, code: 'torn', detail: String(error) }
  }
}

/**
 * Reads once, and on any failure reads again after a short pause.
 *
 * `missing` is retried like `torn` rather than believed: lib/JsonFile.lua's
 * write_atomic removes the old file before renaming the new one into place — a
 * deliberate window it accepted *because* readers retry. Believing the first
 * ENOENT would report "no session" in the middle of every single trial write.
 */
async function readJson(file: string): Promise<RawRead> {
  const first = await readJsonOnce(file)
  if (first.ok) return first

  await delay(RETRY_DELAY_MS)
  return readJsonOnce(file)
}

/** Reads and validates session.json. */
export async function readTaskSession(bridgePath: string): Promise<TaskSessionView> {
  const raw = await readJson(join(bridgePath, SESSION_FILE))
  if (!raw.ok) {
    // No file at all is not a failure: nothing has ever run a session here, or
    // the user deleted it between sessions, which the protocol explicitly allows.
    if (raw.code === 'missing') return { kind: 'none' }
    return { kind: 'unavailable', failure: { code: 'torn', detail: raw.detail } }
  }

  const parsed = parseTaskSession(raw.value)
  if (!parsed.ok) {
    return {
      kind: 'unavailable',
      failure:
        parsed.code === 'schema-unknown'
          ? { code: 'schema-unknown', detail: null, foundSchema: parsed.found }
          : { code: 'shape-invalid', detail: parsed.detail }
    }
  }

  return { kind: 'ready', session: parsed.session, readAt: Date.now() }
}

/**
 * Collapses a view into the things worth re-rendering for.
 *
 * `sequence` alone is enough for the ready case — the mod bumps it on every
 * write and nothing else changes without it (TASK_PROTOCOL.md §3), which is the
 * same dedupe key a file watcher would need for its duplicate events.
 */
function signature(view: TaskSessionView): string {
  switch (view.kind) {
    case 'ready':
      return `ready:${view.session.sequence}`
    case 'unavailable':
      return `unavailable:${view.failure.code}:${view.failure.detail ?? ''}`
    case 'none':
      return 'none'
  }
}

export interface TaskSessionMonitor {
  start(): void
  stop(): void
  /** Reads now, ignoring the mtime gate. For after a command lands. */
  refresh(): Promise<TaskSessionView>
  /** The most recent read, without touching the disk. */
  current(): TaskSessionView
}

/**
 * Watches session.json and reports whenever it changes.
 *
 * `resolveBridgePath` is called per poll rather than captured, so changing the
 * game folder takes effect without tearing the monitor down — same contract as
 * createBridgeMonitor.
 */
export function createTaskSessionMonitor(
  resolveBridgePath: () => string | null,
  onChange: (view: TaskSessionView) => void
): TaskSessionMonitor {
  let view: TaskSessionView = { kind: 'none' }
  let lastSignature = 'none'
  let lastStamp = ''
  let timer: NodeJS.Timeout | null = null
  let inFlight = false

  /**
   * The file's identity as of now, or null when it cannot be stat-ed.
   *
   * Size is checked alongside mtime because a rewrite within the same
   * filesystem timestamp tick is possible — trials can resolve back to back, and
   * the two documents differ by at least one trial record.
   */
  async function stamp(bridgePath: string): Promise<string | null> {
    try {
      const info = await stat(join(bridgePath, SESSION_FILE))
      return `${info.mtimeMs}:${info.size}`
    } catch {
      return null
    }
  }

  async function tick(force: boolean): Promise<TaskSessionView> {
    if (inFlight && !force) return view
    inFlight = true

    try {
      const bridgePath = resolveBridgePath()
      if (!bridgePath) {
        view = { kind: 'unavailable', failure: { code: 'no-game-path', detail: null } }
        lastStamp = ''
      } else {
        const current = await stamp(bridgePath)
        // A stat miss is not concluded here — the file is briefly absent during
        // every atomic write, and readTaskSession is what retries. It only skips
        // the read when the stamp is unchanged *and* readable.
        if (force || current === null || current !== lastStamp) {
          view = await readTaskSession(bridgePath)
          lastStamp = current ?? ''
        }
      }
    } finally {
      inFlight = false
    }

    const next = signature(view)
    if (next !== lastSignature) {
      lastSignature = next
      onChange(view)
    }

    return view
  }

  return {
    start(): void {
      if (timer) return
      void tick(true)
      timer = setInterval(() => void tick(false), POLL_MS)
    },

    stop(): void {
      if (!timer) return
      clearInterval(timer)
      timer = null
    },

    refresh(): Promise<TaskSessionView> {
      return tick(true)
    },

    current(): TaskSessionView {
      return view
    }
  }
}

/**
 * App-side half of the training-task bridge — the command direction.
 *
 * Starts and stops a grading session. Reading what the session produces is
 * task-session.ts's job; the two are split because they are shaped differently
 * (one command/response exchange versus a file that keeps changing), not
 * because the protocol splits them. See TASK_PROTOCOL.md in the mod repo and
 * autorun/func/Task/Bridge.lua for the other end.
 *
 * ## Why this is not bridge.ts
 *
 * It has a separate folder, command file and id sequence because the mod
 * separates the task lifecycle from live recording writes. Modules that have
 * never heard of each other must not compete for one monotonic number. The
 * repeated request/response shape is the protocol being the same protocol, which
 * is the point of having one.
 *
 * ## The spec is built here, not in the renderer
 *
 * A spec's witnesses have to describe what is *actually* in the slots, and main
 * is what holds that — the same reason library:captureSlot takes a slot number.
 * The renderer names which slots it wants graded; the
 * witness comes from main's own snapshot of the mod's recording_slots.json, computed by
 * the same `timelineWitness` the mod re-derives per trial.
 */

import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  TASK_ACTION_LIST_REVERSALS,
  TASK_ACTION_START,
  TASK_ACTION_STOP,
  TaskCommandSchema,
  TaskResultSchema
} from '@fgcnote/shared/recording/training-task-bridge'
import type {
  LiveReversals,
  TaskCommand,
  TaskSpec
} from '@fgcnote/shared/recording/training-task-bridge'
import { resolveTaskBridgePath } from './config'
import { desktopFilesystem } from './desktop-filesystem'
import type {
  LiveReversalsResult,
  TaskOpResult,
  TaskStartResult
} from '../shared/types'

const COMMAND_FILE = 'command.json'
const RESULT_FILE = 'result.json'

/**
 * How long to wait for the game to answer.
 *
 * Both halves of a start are quick — the mod validates the spec and arms a
 * watcher, no buffer writes — so this is almost entirely the mod's own poll
 * backing off to once every 5s when the bridge has been idle. Same figure the
 * headless driver uses, and the reason a first command can feel slow.
 */
const RESULT_TIMEOUT_MS = 15_000
const RESULT_POLL_MS = 250

function readJson(path: string): Record<string, unknown> | null {
  if (!existsSync(path)) return null
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf-8')) as unknown
    if (typeof parsed !== 'object' || parsed === null) return null
    return parsed as Record<string, unknown>
  } catch {
    // Torn read while the other side writes; the caller retries.
    return null
  }
}

/**
 * Next command id, derived from the files on disk rather than kept in memory.
 *
 * The mod ignores any id at or below the last one it handled, so a counter that
 * restarts with the app would produce commands that are silently dropped while
 * the UI waits for a result that is never coming.
 */
function nextCommandId(bridgePath: string): number {
  const previousCommand = readJson(join(bridgePath, COMMAND_FILE))
  const previousResult = readJson(join(bridgePath, RESULT_FILE))

  const commandId = Number(previousCommand?.id)
  const resultId = Number(previousResult?.id)

  return (
    Math.max(
      Number.isFinite(commandId) ? commandId : 0,
      Number.isFinite(resultId) ? resultId : 0
    ) + 1
  )
}

const wait = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms))

/** Creates the bridge folder so the mod polls an existing directory. */
export function ensureTaskBridgeFolder(): string | null {
  const bridgePath = resolveTaskBridgePath()
  if (!bridgePath) return null
  try {
    desktopFilesystem.bridge.ensureDirectory(bridgePath)
    return bridgePath
  } catch {
    return null
  }
}

/**
 * What `send` hands back: the common outcome, plus the fields only some actions
 * answer with. Null rather than optional on the extras, so a caller that reads
 * one for the wrong action gets a value it has to handle rather than
 * `undefined` sliding through.
 */
interface SendResult extends TaskOpResult {
  reversals: LiveReversals | null
  characterName: string | null
}

/** Writes one command and resolves once the mod reports an outcome. */
async function send(command: TaskCommand, bridgePath: string): Promise<SendResult> {
  const validated = TaskCommandSchema.safeParse(command)
  if (!validated.success) {
    return {
      ok: false,
      reversals: null,
      characterName: null,
      message:
        'Could not build a valid request: ' +
        validated.error.issues
          .map((issue) => `${issue.path.join('.') || '(root)'} ${issue.message}`)
          .join('; ')
    }
  }

  try {
    desktopFilesystem.bridge.writeJson(join(bridgePath, COMMAND_FILE), validated.data)
  } catch (error) {
    return {
      ok: false,
      reversals: null,
      characterName: null,
      message: 'Could not write to the game folder: ' + String(error)
    }
  }

  const resultPath = join(bridgePath, RESULT_FILE)
  const deadline = Date.now() + RESULT_TIMEOUT_MS

  while (Date.now() < deadline) {
    await wait(RESULT_POLL_MS)

    const raw = readJson(resultPath)
    if (!raw) continue

    const result = TaskResultSchema.safeParse(raw)
    // Ignore stale results from earlier commands, and half-written files.
    if (!result.success || result.data.id !== validated.data.id) continue

    return {
      ok: result.data.ok,
      message: result.data.message,
      taskId: result.data.taskId ?? null,
      reversals: result.data.reversals ?? null,
      characterName: result.data.characterName ?? null
    }
  }

  return {
    ok: false,
    timedOut: true,
    reversals: null,
    characterName: null,
    message:
      'No response from the game. Check that SF6 is running with the mod loaded ' +
      'and that you are in Training Mode.'
  }
}

/**
 * A task id for one run.
 *
 * Opaque to the mod, echoed back everywhere, and the archive's file name. It
 * carries the definition's id when there is one, so every session a saved task
 * has produced is greppable — but each run gets its own suffix, because two runs
 * of the same drill are two sessions and must not overwrite each other.
 */
export function mintTaskId(definitionId?: string): string {
  const stamp = Date.now()
  return definitionId ? `${definitionId}-${stamp}` : `desktop-${stamp}`
}

/**
 * `mintTaskId`'s inverse: which saved task a session came from, or null.
